  if(mode==='ONE_SHOT')return <button className="manual-action nodrag nopan" disabled={disabled} onPointerDown={event=>event.stopPropagation()} onClick={event=>{event.stopPropagation();invoke('trigger')}}>TRIGGER PULSE</button>;
