function Runtime(){const[rows,setRows]=useState<Record<string,unknown>>({});useEffect(()=>{const f=()=>api<Record<string,unknown>>('/api/runtime').then(setRows);void f();const i=setInterval(f,1000);return()=>clearInterval(i)},[]);return <Table title="LIVE RUNTIME" rows={Object.entries(rows).map(([nodeId,value])=>({nodeId,...value as object}))}/>}


